insert into public.questions (question_id,paper_id,question_number,question_type,question_points,question_text,option_a,option_b,option_c,option_d,option_e,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('113-1301-048','113-1301',48,'single_choice',2,'甲對乙提出傷害罪之告訴，惟檢察官偵查終結作成不起訴處分，甲不服聲請再議，惟遭上級檢察機關 以無理由駁回。關於甲對此請求救濟之敘述，下列何者正確？','甲可以直接向管轄法院提起自訴','甲可以在接受上開再議駁回之處分書後10 日內，委任律師提出理由狀，向管轄第一審法院聲請准 許提起自訴','此時不起訴處分已經確定，甲在現行法之下，並無任何救濟管道','再議駁回之處分，性質上屬於行政處分之一，得以訴願之方式救濟之',null,'刑事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-1301-049','113-1301',49,'single_choice',2,'甲因涉嫌與跨國境詐欺集團之人共犯加重詐欺、洗錢等罪嫌，已被羈押。甲之辯護人與甲接見時，替 甲傳遞教其他人避罪的紙條予詐欺集團之人。檢察官認此有串證之虞，是否可直接命令看守所限制辯 護人與羈押之被告甲接見或互通書信？','可以，檢察官偵查中對此有強制處分權','原則上不可以，檢察官必須向法院聲請核發限制書，但遇有急迫情形時，得先為必要之處分，並應 於24 小時內聲請該管法院補發限制書','原則上不可以，檢察官必須向法院聲請核發限制書，但遇有急迫情形時，得先為必要之處分，並應 於3 日內聲請該管法院補發限制書','一律不可以，檢察官僅得向法院聲請核發限制書',null,'刑事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-1301-050','113-1301',50,'single_choice',2,'甲向法院自訴乙對其涉有刑法第339 條第1 項之詐欺取財罪嫌，法院審理中，甲具狀撤回對乙之自 訴，法院應如何處理，下列敘述何者正確？','認撤回合法，為不受理判決','認撤回合法，以行政報結，並由書記官將撤回自訴事由通知被告','認撤回不合法，繼續審理','認撤回不合法，以裁定駁回',null,'刑事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-1301-051','113-1301',51,'single_choice',2,'檢察官從報上得知甲接受專訪時表示曾於10 年前，因不堪乙苦苦哀求，幫一心尋死的乙注射毒藥， 檢察官於簽准分案後，命檢察事務官進行案情分析及擬定偵查策略，乙之妻丙亦在報紙得知上開消息 後，立即委請律師向法院提起自訴甲犯加工自殺罪。下列敘述何者正確？','丙非犯罪之直接被害人，依法不得提起自訴','本件已開始偵查，丙依法不得提起自訴','甲所涉及之加工自殺罪係已得乙之囑託，且乙之遺書亦清楚表示「不得為難甲」，故丙因不得與乙 明示之意思相反，而不得提起自訴','本件檢察官雖已得知有犯罪嫌疑，命檢察事務官進行相關案情分析，尚未開始偵查，故丙雖提起自 訴在後，仍得為之',null,'刑事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-1301-052','113-1301',52,'single_choice',2,'甲涉犯過失傷害罪嫌，經檢察官偵查終結，為緩起訴處分，緩起訴期間2 年。依實務見解，下列敘述 何者正確？','檢察官命被告向公庫支付一定金額，須得被告之同意','檢察官命被告向被害人道歉，須得被害人同意','緩起訴期間屆滿後，未經撤銷時，本案仍無實質確定力','緩起訴期間，被害人得提起自訴',null,'刑事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-1301-053','113-1301',53,'single_choice',2,'法院依據國民法官法完成審理程序後，進入評議階段，經職業法官與國民法官針對案情進行討論後， 經評議有罪者五票（含一票職業法官），無罪者四票（含兩票職業法官）。此時合議庭應如何處理？','應為無罪判決','適用國民法官法之案件均為重大刑事案件，合議庭應為一致決','審判長應向國民法官提示審理過程中之特定重要證據，請國民法官重新審酌','因有罪認定已取得多數票，且包括一名職業法官，因此審判長可以結束評議程序，並由合議庭作成 有罪判決',null,'刑事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-1301-054','113-1301',54,'single_choice',2,'下列何種情形，被告未到庭，法院不得逕行審判？','被告心神喪失或因疾病不能到庭，顯有應諭知無罪或免刑判決之情形','應諭知有期徒刑之適用簡式審判程序案件','法院認為應科拘役、罰金或應諭知免刑或無罪之案件，被告經合法傳喚無正當理由不到庭者','最重本刑為拘役或專科罰金之罪得僅由代理人到庭之案件',null,'刑事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-1301-055','113-1301',55,'single_choice',2,'對於法院形式判決之敘述，依實務見解，下列何者錯誤？','通姦罪判決確定後，通姦罪經大法官解釋宣告違憲並自宣示之日起失其效力，檢察總長就原因案件 提起非常上訴，最高法院應諭知免訴','個案非屬我國刑法適用法效力範圍時，法院應諭知不受理','無管轄權之自訴案件，應諭知管轄錯誤，並同時諭知移送於管轄法院','免訴、不受理與管轄錯誤之判決，得不經言詞辯論為之',null,'刑事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-1301-056','113-1301',56,'single_choice',2,'行合議審判之案件，審判長指定一人為受命法官行準備程序，下列關於準備程序受命法官得為訴訟行 為之敘述，何者錯誤？','詢問檢察官起訴範圍及是否要變更起訴法條','被告主張警詢自白係遭警察刑求，受命法官遂於準備庭中勘驗被告於警詢中之錄音光碟','被告主張證人警詢筆錄為傳聞證據無證據能力，受命法官當庭裁定證人警詢筆錄無證據能力，並曉 諭檢察官聲請傳喚證人到庭','被告經合法傳喚無正當理由不到庭者，受命法官仍可對到庭之人行準備程序',null,'刑事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-1301-057','113-1301',57,'single_choice',2,'辯護人於準備程序向法院聲請於審判期日調查證人甲後，法院得知甲將於近日被派往倫敦分公司任 職，應無法於審判期日出庭。下列敘述何者正確？','法院應駁回調查證人甲之聲請','法院逕行傳喚甲，並不待當事人到場直接訊問','法院不傳喚甲，直接以偵查中筆錄作為書證，於審判期日調查之','法院得於審判期日前先行訊問甲，並應行交互詰問程序',null,'刑事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-1301-058','113-1301',58,'single_choice',2,'檢察官起訴被告於民國109 年間同時持有A、B 二把改造手槍，涉想像競合犯非法持有手槍1 罪嫌。 第一審法院判決被告持有A 槍有罪，持有B 槍部分則於理由內說明不另為無罪之諭知。第二審法院 駁回檢察官及被告之上訴，維持第一審法院判決。下列敘述何者正確？','非法持有手槍罪係得上訴第三審之案件，檢察官就第二審判決全部都可以提起第三審上訴，不受任 何限制','被告僅對第二審有罪部分上訴，檢察官未上訴，上訴範圍不及於不另為無罪諭知部分','被告僅對第二審有罪部分上訴，檢察官未上訴。第三審如認被告上訴有理由，基於審判不可分原則， 應將不另為無罪諭知部分併同發回第二審更為審理','僅檢察官對第二審有罪部分上訴，依上訴不可分原則，及於不另為無罪諭知部分，第三審法院應全 部審理',null,'刑事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-1301-059','113-1301',59,'single_choice',2,'甲因偽造文書等案件，經第二審法院判處相關罪刑後，甲於法定上訴期間內提起第三審上訴，然其上 訴書狀並未敘述上訴理由，僅記載「理由後補」。第二審法院收受甲提出之上訴書狀後，應如何處理， 最為正確？','以裁定定期命甲補提上訴理由，逾期不補正，則以裁定駁回上訴','以裁定定期命甲補提上訴理由，逾期不補正，則以判決駁回上訴','毋庸以裁定定期命甲補提上訴理由，直接以判決駁回上訴','毋庸以裁定定期命甲補提上訴理由，直接送最高法院審判',null,'刑事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-1301-060','113-1301',60,'single_choice',2,'A 因使用GPS 追蹤器調查他人行蹤，一審法院判決A 有罪，二審法院認原審判決適用法條有誤，撤 銷後亦改判有罪。A 上訴第三審，第三審法院以上訴違背法律上之程式，判決駁回。關於本件之非常 上訴，下列敘述何者正確？','檢察總長為被告利益，應以第三審程序判決為對象提起非常上訴','檢察總長應以第二審實體判決為對象提起非常上訴','檢察總長得以最高法院法律見解已有變更作為非常上訴理由','非常上訴採強制辯護制度，A 未選任辯護人者，應由審判長為其指定公設辯護人或律師',null,'刑事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-1301-061','113-1301',61,'single_choice',2,'關於法官、檢察官及律師依照專業倫理應遵守事項，下列何者錯誤？','法官於任職期間，不但應該避免參加政治活動，也不可以在上班以外的時間公開支持、反對或評論 任何政黨、政治團體','檢察官應嚴守偵查不公開原則，但媒體報導之內容與偵查案件事實不符而有澄清之必要時，得經所 屬機關首長授權，對外就案情為必要之說明','律師先受房屋租約雙方委任，擔任某租賃契約之見證人。嗣後，律師受該出租人委任向該承租人起 訴請求返還系爭租賃物，其受委任毋庸取得該承租人之同意','提升專業能力為法律人重要的基本倫理，法官、檢察官及律師均負有從事在職進修之義務',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-1301-062','113-1301',62,'single_choice',2,'法官甲及法官乙為夫妻關係，服務於同一法院。法官甲審理承租人A 主張終止租約，請求出租人B 返 還押租金之爭議。言詞辯論期日，對於A 與B 間是否繼續存在租賃關係之爭點，當庭致電法官乙（另 案承辦A 與B 間給付租金事件）詢問其對於系爭爭點之心證，並以該心證作為勸諭和解之基礎。法 官甲之行為是否違反法官倫理規範？','違反，因為法官甲、乙既為配偶關係，不應分別承辦相關案件，應屬當然迴避事由','違反，因為法官甲當庭致電法官乙，逕依法官乙之認定作為和解基礎，易使當事人對於法官審判獨 立性產生疑慮','不違反，因為法官甲用心良苦，係為避免兩案見解歧異，產生裁判矛盾之風險','不違反，因為法官甲基於便民措施，目的乃為促成和解，減少訟源',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-1301-063','113-1301',63,'single_choice',2,'甲法官擔任刑事審判工作多年，經驗豐富著有聲譽，獲某大學邀聘講學，甲即合法申報，並獲機關首 長許可後兼職授課。下列行為何者違反法官倫理規範？','甲於授課內容批評最高法院之確定判決見解錯誤，重大影響當事人權利','甲應邀參加學校期末聚餐，席間並與多名學生合影。嗣後學生乙將合影照片張貼於社群媒體，並標 註甲之司法公職身分','甲於授課過程中，學生A 因家族成員之民事糾紛涉訟，向甲請教相關法律問題。經甲詢問案情後即 於課堂答覆A，並提供具體之法律意見及訴訟策略','甲選擇由某出版社為其出版之著作，以之作為課程教材，並商請出版社以七折特別價惠價出售給修 課學生',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-1301-064','113-1301',64,'single_choice',2,'甲法官與其夫乙為某航空公司貴賓會員，某日在使用機場貴賓室時，乙因故摔倒受傷，甲法官當場表 明法官身分揚言提告，航空公司依甲當場之要求，隔日派員至甲之辦公室商談和解事宜，下列敘述何 者正確？','甲法官如係利用下班時間為之，並未違反法官倫理規範','甲法官如獲乙授權談判，並未違反法官倫理規範','甲法官表明法官身分，利用辦公處所進行私人事務之行為已違反法官倫理規範','甲法官所為係行使其法定權利，並未違反法官倫理規範',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('113-1301-065','113-1301',65,'single_choice',2,'關於法院首長對於所屬法官進行職務監督時，下列何者非屬法院首長職務監督的處分樣態？','制止法官違法行使職權','糾正法官不當言行','督促法官依法迅速執行職務','命令移轉法官審理中之個案，改由其他法官審理',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('113-1301-066','113-1301',66,'single_choice',2,'甲、乙、丙、丁四人為大學同學，甲為執業律師，乙、丙、丁於民國105 年間擔任檢察官，惟丙於109 年轉任律師，並與甲合夥經營律師事務所，甲於111 年和A 女結婚。下列何者違反檢察官倫理？','丙轉任律師時，乙和丁基於同事情誼，具名致送花籃書寫「開幕致慶」','乙出席甲和A 的婚宴時，包禮金3,000 元給甲','甲律師、乙檢察官同時擔任行政院公共工程委員會之申訴委員','乙出席甲和A 的婚宴時，丙當時擔任乙承辦案件中被告B 的辯護人，且婚宴中乙與丙、B 同桌， 因屬正常社交，乙繼續用餐至婚宴結束',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('113-1301-067','113-1301',67,'single_choice',2,'甲檢察官偕同書記官、法醫外出執行相驗屍體外勤任務，於現場相驗完畢後，已逾中午用餐時間，下 列何者不違反檢察官倫理規範之要求？','為求方便且有助於檢、警聯繫，甲檢察官與共同前往相驗書記官、法醫，接受報驗之轄區司法警察 招待用餐','甲檢察官自行出錢，就近請書記官、法醫便餐','甲檢察官自行前往他處用餐，請報驗之轄區司法警察招待書記官、法醫便餐','甲檢察官與所率書記官、法醫，均不可接受報驗之轄區司法警察招待用餐，但可接受相驗之家屬付 費訂餐',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('113-1301-068','113-1301',68,'single_choice',2,'為端正檢察官風紀、促使檢察官嚴守辦案程序、遵守檢察官倫理規範，對違反之檢察官有懲戒之規定。 下列敘述何者正確？','檢察官應受懲戒之同一行為，不受二次懲戒','檢察官應受懲戒之同一行為已受刑罰或行政罰之處罰者，因一行為不二罰，不得再予以懲戒','法官與檢察官性質不同，法官之懲戒由懲戒法院職務法庭審理，檢察官之懲戒由法務部下設檢察官 人事審議委員會審理','檢察官違反檢察官倫理規範，不分情節輕重，均應付個案評鑑，認有懲戒之必要者，得移送懲戒',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('113-1301-069','113-1301',69,'single_choice',2,'律師之執行職務行為，下列何者不違反律師倫理？','擔任詐欺罪之刑事案件之辯護人，與被告約定若獲無罪判決，以詐欺所得金額的百分之二十作為後 酬','代理原告起訴請求移轉不動產所有權，約定若勝訴，原告應以該不動產價值之十分之一作為後酬','代理土地所有權人請求拆屋還地，在訴訟進行中，受讓該土地所有權','代理妻起訴同時請求離婚及離婚後之剩餘財產，並約定全部勝訴後，以法院判決剩餘財產金額之百 分之十作為後酬',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('113-1301-070','113-1301',70,'single_choice',2,'當事人A 委任甲律師進行民事訴訟，訴訟進行中，A 要求甲律師將卷宗資料全部影印一份給A，甲律 師應如何處理？','訴訟還在進行中，不可以影印給A，要等到訴訟終結之後才可以影印給A','甲律師自己寫的狀紙以及法院筆錄可以影印給當事人，對造律師的狀紙則必須先取得對造律師同意 才可以影印','甲應該依照A 的要求將卷宗內的資料全部影印給A','甲律師自己寫的狀紙可以影印給當事人，但法院筆錄及對造律師的狀紙要取得法院及對造律師同意 才可以影印給A',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('113-1301-071','113-1301',71,'single_choice',2,'有關利益衝突之敘述，下列何者未違反律師倫理規範？','A 曾委託甲律師處理其對B 之請求禁止B 侵害A 之專利權訴訟事件。該案件終結後，第三人C 委 託甲律師對A 提起分割某不動產之訴訟','A 與B 原為夫妻，後協議離婚，A 委請甲律師擔任離婚協議書之見證人。後A 與B 因離婚協議書 約定事項發生爭議，B 委任甲律師對A 提起訴訟','甲律師曾受A 公司委任對於董事B 的競業禁止事項出具意見。甲後來接受B 的委任，對A 公司請 求停止執行關於B 的競業禁止之董事會決議','甲律師聘僱乙律師，甲允許乙自行接案。若乙律師受當事人A 之委任，甲得同時接受同一案件對造 B 的委任',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('113-1301-072','113-1301',72,'single_choice',2,'甲律師擔任A 公司之法律顧問，因而得知A 公司所推出的金融商品其實是一個詐欺騙局，會讓投資 大眾遭受重大的財產損失。其後，甲律師終止與A 公司的委任關係。在某次參加大學同學聚會時，甲 律師的同學乙談到想要投資A 公司的該金融商品，甲可不可以警告乙該商品其實是一個詐欺騙局？','可以，A 公司推出的金融商品是會造成乙財產重大損害的犯罪行為，可以揭露','不可以，律師應該為當事人保守秘密，絕對不可以洩漏','不可以，因為金融詐欺只會造成財產損害，沒有危害到生命或身體','如果甲律師還是A 公司的顧問就不可以，現在已經不是顧問，應該就可以',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('113-1301-073','113-1301',73,'single_choice',2,'某大學法律系甲教授擔任A 及B 兩人間工程承攬爭議事件之主任仲裁人，仲裁判斷有利於A。不久， 甲教授便離開教職，從事律師工作。B 因不服該仲裁結果，提起撤銷仲裁判斷之訴訟，A 欲聘請甲律 師擔任其訴訟代理人，下列敘述何者正確？','因仲裁判斷結果有利於A，甲可以受任擔任A 之訴訟代理人，因其熟悉案情，有助於維護A 之權益','甲律師先前擔任仲裁人，即使得A 與B 之同意，甲律師仍不得在撤銷仲裁判斷之訴訟中擔任A 之 訴訟代理人','因A 聘請甲律師擔任訴訟代理人時，等同A 已認可並接受該利害衝突，故甲律師接受委任未違反 律師倫理','甲不可接受委任，因其未得仲裁協會同意',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('113-1301-074','113-1301',74,'single_choice',2,'甲是律師事務所的合夥人，乙為事務所的受僱律師。乙為求勝訴，私下會見已委任律師之對造當事人。 下列敘述何者正確？','乙之行為有助於當事人勝訴，縱使違反其他法令，但不違反律師倫理規範','委任人是委任甲處理案件，乙只是甲的受僱律師，乙之行為不影響甲的律師倫理義務','乙律師知道對造已委任律師，不應該私下會見對造','因乙為甲所僱用，甲不得將此事通知乙所屬之律師公會進行懲戒程序',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('113-1301-075','113-1301',75,'single_choice',2,'甲律師受僱於某事務所並被指派承辦當事人A 的案件，因為甲律師即將離職，受僱於另一事務所，甲 律師就向A 說明因只有他最清楚案情，希望A 能夠與原事務所終止委任，繼續由甲律師承辦。甲律 師之行為有沒有違反律師倫理相關規範？','有，受僱律師離職時不能夠促使當事人轉委任自己為受任人','沒有，律師業務的競爭本來就各憑本事，除非甲律師有惡意詐欺脅迫之行為，否則要求並促使當事 人轉委任自己，為法之所許','如果這個案件真的只有甲律師瞭解，甲律師可以促請當事人轉委任自己。如果原事務所還有其他律 師瞭解案情就不可以','如果甲律師新任職的事務所同意就可以，不同意就不行',null,'法律倫理','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('114-2301-001','114-2301',1,'single_choice',2,'憲法本文及增修條文之下列何種規定，得導出我國有民主國之性質？','總統及立法院均由人民直接選舉產生','總統公布法律、發布命令，須經行政院院長之副署','國家重要事項須經行政院院會議決','國家權力劃分為五權，分設五院行使之',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-2301-002','114-2301',2,'single_choice',2,'依司法院解釋意旨及憲法法庭裁判，關於憲法第155 條：「人民之老弱殘廢，無力生活，……國家應 予以適當之扶助與救濟」，下列敘述何者錯誤？','租稅優惠為國家得採取保障人民生存與生活之扶助措施之一','國家保障視障者之工作權屬特別重要公共利益','憲法特別著重弱勢者之保障，第155 條即為例證之一','對身心障礙者優惠性差別待遇之合憲性，應採寬鬆之合理性審查',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-2301-003','114-2301',3,'single_choice',2,'依司法院解釋意旨及憲法法庭裁判，關於政黨之敘述，下列何者錯誤？','政黨應服膺自由民主憲政秩序','政黨與其他團體受憲法保障與限制之程度無平等原則之適用','國家應致力於建立並確保複數政黨得以自由形成發展與公平參與選舉之法治環境','國家得對政黨之財產權加以更多限制或給予政黨補助金',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-2301-004','114-2301',4,'single_choice',2,'有關家庭暴力防治法中之保護令，依司法院解釋意旨及憲法法庭裁判，下列敘述何者錯誤？','涉及人身自由之限制，應以法律定之','法律已就人身之處置為明文規定者，得透過具體明確之授權，委由主管機關執行之','有關人身自由限制之決定，得由法院依法定程序以裁定為之','民事保護令並不涉及人身自由之限制',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-2301-005','114-2301',5,'single_choice',2,'下列何者非屬釋憲實務對於宗教自由保障之意旨？','宗教結社屬宗教自由之絕對保障','國家考試不得基於人民之特定信仰給與加分優待','國家不得基於人民之特定信仰為理由予以不利益','不許人民以宗教理由免除服兵役義務',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-2301-006','114-2301',6,'single_choice',2,'依司法院解釋意旨及憲法法庭裁判，關於大學自治之敘述，下列何者錯誤？','為避免學術自由受國家不當干預，立法機關僅得在合理之範圍內對大學事務加以規範','大學為確保學位之授予具備一定之水準，得於合理及必要之範圍內，訂定有關取得學位之資格條件','審理大學學生提起行政爭訟事件，應本於維護大學自治之原則，對大學之專業判斷予以適度之尊重','大學法明定大學應設教務處、學生事務處、總務處之內部組織，限制大學之自主組織權而與保障大 學自治之意旨相牴觸',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-2301-007','114-2301',7,'single_choice',2,'關於生命權保障，下列敘述何者錯誤？','我國憲法對生命權之保障依據，依司法院解釋意旨及憲法法庭裁判，應係憲法第22 條其他自由權 利的保障範圍','公民及政治權利國際公約規定，任何被判處死刑的人應有權請求赦免或減刑，但赦免法未有類似規 定，使被判處死刑的人有權請求獲得赦免','法律規定不得對未滿18 歲之人處以死刑，符合兒童權利公約之精神','公民及政治權利國際公約規定，未廢除死刑之國家，非犯情節最重大之罪，不得科處死刑',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('114-2301-008','114-2301',8,'single_choice',2,'有關平等原則，下列敘述何者錯誤？','人民無權主張不法之平等','行政機關依裁量基準而形成之慣例，發生間接對外效力，屬於平等原則之內涵','平等原則可以導出行政機關須受行政慣例之自我拘束','夜市攤販甲因逃漏營業稅而應予補稅，甲有權請求稅務機關要求其他夜市攤販補稅',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-2301-009','114-2301',9,'single_choice',2,'關於訴訟權保障，下列敘述何者錯誤？','訴訟救濟由何種法院審理，為訴訟權保障之核心內容，非屬立法形成自由','受刑事有罪判決之被告，應有上訴救濟之機會，屬於訴訟權保障之核心內容','直接審理、言詞辯論、對審及辯護制度係本於正當法律程序之原則','有權利即有救濟，權利受公權力侵害者，皆享有訴訟救濟之基本權',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-2301-010','114-2301',10,'single_choice',2,'計程車駕駛人觸犯法定之罪，經法院判決有期徒刑以上之刑，吊扣或廢止其執業登記，依司法院解釋 意旨及憲法法庭裁判，係對於何種自由之限制？','遷徙自由','職業選擇自由之主觀條件','職業選擇自由之客觀條件','職業自由之執行方式',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-2301-011','114-2301',11,'single_choice',2,'關於服兵役之義務，下列敘述何者錯誤？','甲男因宗教信仰而不願使用武器，向主管機關申請獲准服替代役，故甲男因此免除服兵役之義務','中華民國男子依法有服兵役之義務，係立法者鑒於男女之生理上差異，所為之合理差別待遇','為防衛國家之安全，在實施徵兵制之國家，即規定人民有服兵役之義務','因有痼疾不堪服役者，得依法律規定免除服兵役之義務',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('114-2301-012','114-2301',12,'single_choice',2,'依司法院解釋意旨及憲法法庭裁判，憲法第22 條規定之基本權利，下列何者受絕對保障？','原住民之身分認同權','原住民依循文化傳承從事狩獵活動','個人自主控制其個人資料之資訊隱私權','人民內在精神活動之思想自由',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
